<?php
namespace App\Reports\Standard;
use App\Reports\Queries\PurchaseReportQuery;use App\Services\Reports\Contracts\StandardReport;use App\Services\Reports\ReportResult;
final class PurchaseDetailReport extends AbstractStandardReport implements StandardReport{
 public function __construct(private readonly PurchaseReportQuery $purchase){}public function code():string{return 'PURCHASE_DETAIL';}public function parameters():array{return array_merge($this->periodParameters(),$this->purchaseFilterParameters());}
 public function run(array $p):ReportResult{$m=PurchaseReportQuery::metricSelects();$rows=$this->purchase->postedInvoiceLines($p)->select('p.document_no','p.document_date','p.due_date','po.document_no as purchase_order_no','pr.document_no as receipt_no','bu.code as business_unit','v.code as vendor_code','v.name as vendor_name','i.code as item_code','i.name as item_name','cat.name as category','b.name as brand','loc.code as location','l.quantity','l.unit_price','l.discount_amount','l.tax_amount')->selectRaw($m['purchase_amount'].' AS purchase_amount')->selectRaw($m['grand_total'].' AS grand_total')->orderBy('p.document_date')->orderBy('p.document_no')->orderBy('l.id')->limit((int)config('reports.screen_row_limit',5000))->get()->all();return new ReportResult('Purchase Detail',[$this->col('document_no','Invoice'),$this->col('document_date','Date','date'),$this->col('due_date','Due Date','date'),$this->col('purchase_order_no','Purchase Order'),$this->col('receipt_no','Receipt'),$this->col('business_unit','Business Unit'),$this->col('vendor_code','Vendor'),$this->col('vendor_name','Vendor Name'),$this->col('item_code','Item'),$this->col('item_name','Item Name'),$this->col('category','Category'),$this->col('brand','Brand'),$this->col('location','Location'),$this->col('quantity','Qty','quantity',4),$this->col('unit_price','Unit Price','money'),$this->col('purchase_amount','Purchase','money'),$this->col('tax_amount','Tax','money'),$this->col('grand_total','Total','money')],$rows,['Purchase'=>$this->moneySum($rows,'purchase_amount')],['quantity'=>$this->qtySum($rows,'quantity'),'purchase_amount'=>$this->moneySum($rows,'purchase_amount'),'tax_amount'=>$this->moneySum($rows,'tax_amount'),'grand_total'=>$this->moneySum($rows,'grand_total')]);}
}
